"""Data model for the ledger."""

from dataclasses import dataclass, field
from datetime import date


@dataclass
class Transaction:
    """One line of a ledger file.

    amount is positive for spending and negative for a refund.
    """

    when: date
    category: str
    amount: float
    description: str = ""
    tags: list = field(default_factory=list)

    @property
    def month(self) -> str:
        return self.when.strftime("%Y-%m")

    def is_refund(self) -> bool:
        return self.amount < 0

