"""Summaries over a list of transactions."""

from collections import defaultdict


def totals_by_category(transactions) -> dict:
    """Total spent per category, sorted by category name."""
    totals = defaultdict(float)
    for t in transactions:
        if t.amount <= 0:
            continue
        totals[t.category] += t.amount
    return dict(sorted(totals.items()))


def monthly_totals(transactions) -> dict:
    """Net amount per YYYY-MM month, sorted by month."""
    totals = defaultdict(float)
    for t in transactions:
        totals[t.month] += t.amount
    return dict(sorted(totals.items()))


def largest(transactions, n=3) -> list:
    """The n largest amounts, biggest first."""
    return sorted(transactions, key=lambda t: t.amount, reverse=True)[:n]


def format_table(rows: dict) -> str:
    """Render a name->number mapping as aligned text."""
    if not rows:
        return "(nothing)"
    width = max(len(k) for k in rows)
    return "\n".join(f"{k.ljust(width)}  {v:10.2f}" for k, v in rows.items())
